const idFor = (kind, name) => `workspace.${kind}.${name}`;
const references = (name, authKeys = [], addAlternative = false, followingActions = [], mountKeys = [], relatedSourceAnchorIds = []) => [
  idFor('handler', name),
  ...(client[name] ? [idFor('client', name)] : []),
  ...(ui[name] ? [idFor('ui', name)] : []),
  ...authKeys.map(key => idFor('authority', key)),
  ...(addAlternative ? ['workspace.alternative.currentRoleConfig.handler', 'workspace.alternative.currentRoleConfig.client'] : []),
  ...followingActions.flatMap(key => [`workspace.following.${key}.handler`, `workspace.following.${key}.client`]),
  ...mountKeys.map(key => `workspace.mount.${key}`),
  ...relatedSourceAnchorIds,
];

export const REVIEWS = rows.map(row => {
  const sourceAnchorIds = references(row.name, row.auth ?? [], row.classification?.startsWith('legacy/'),
    row.following ?? [], row.mounts ?? mountedIn[row.name] ?? [], row.relatedSourceAnchorIds ?? []);
  const servingStatus = row.classification === 'legacy/deprecated-internal-compatibility'
    ? 'legacy-endpoint-not-used-by-current-control'
    : row.classification === 'genuinely-unserved' ? 'genuinely-unserved' : 'served-ui-path';
  return {
    exportName: row.name,
    classification: row.classification ?? 'served-ui-path',
    productPath: {
      status: servingStatus,
      surface: row.surface,
      invocation: row.invocation,
      sourceAnchorIds,
    },
    actor: {
      family: row.actor,
      identities: row.identities,
      conditionalOverrides: row.conditionalOverrides ?? actorOverrides[row.name] ?? [],
      sourceAnchorIds,
    },
    requirements: { summary: row.req, sourceAnchorIds },
    costs: { summary: row.cost, sourceAnchorIds },
    consequences: { summary: row.result, sourceAnchorIds },
    blockers: { summary: row.block, sourceAnchorIds },
    nextActor: { summary: row.next, sourceAnchorIds },
    clientCallTrace: {
      status: row.classification === 'legacy/deprecated-internal-compatibility'
        ? 'legacy-service-wrapper-not-current-control'
        : client[row.name] ? 'current-client-service-call' : 'current-mounted-service-call',
      sourceTreeSha256: null,
      identifierReferenceCount: null,
      interpretation: row.invocation,
      sourceAnchorIds,
    },
    guidance: {
      status: row.classification === 'legacy/deprecated-internal-compatibility'
        ? 'current-guidance-on-served-alternative'
        : row.classification === 'genuinely-unserved' ? 'not-present-in-current-ui' : 'current-source-guidance',
      summary: row.guidance,
      sourceAnchorIds,
    },
  };
});
